                  "person_days": {"type": "array", "items": {"type": "number"}, "minItems": 2, "maxItems": 2},
                  "basis": {"type": "string", "description": "中文：估算依据，引用 code_partition 桶（如「needs_adaptation 桶 3.2k LOC，主要为 src/win32」）或 arch_specific/blockers"}}}}}},
        "confidence": {"type": "string", "enum": ["high", "medium", "low"],
          "description": "★闭轴：本评估的置信度。存在 required 且 target_status=unknown 的 target_assumptions 时归一确定性下调至至多 medium（原值存 confidence_model）；沿依赖树取 min 传播（rollupConfidence）。"},
        "confidence_model": {"type": ["string", "null"],
          "description": "归一前模型给出的 confidence 原值（单次记录、供 required+unknown 下调后仍可再派生/复原）。"},
        "unadaptable_apis": {"type": "array", "items": {
